  {"name": "Stonecunning", "desc": "As a Bonus Action, you gain Tremorsense with a range of 60 feet for 10 minutes. You must be on a stone surface or touching one. You can use this trait a number of times equal to your Proficiency Bonus per Long Rest."}
]

[
  {
    "name": "Darkvision",
