    "display": "You have Advantage on saving throws you make to avoid or end the Charmed condition on yourself."
  },
  {
    "name": "Trance",
    "logic": {"type": "immunity", "condition": "Magical Sleep", "rest_modification": "4 hours"},
    "display": "You don't need to sleep, and magic can't put you to sleep. You can finish a Long Rest in 4 hours."
  }
]

[
  {
    "name": "Giant Ancestry",
    "display": "You trace your ancestry to a type of giant, gaining a specific magical benefit. (See Lineage for options)"
  },
  {
    "name": "Large Form",
    "logic": {"type": "bonus_action", "usage": "proficiency_bonus", "recovery": "long_rest", "unlock_level": 5},
    "display": "Starting at level 5, you can change your size to Large for 10 minutes."
  },
