    "name": "Brave",
    "logic": {"type": "advantage_saving_throw", "condition": "Frightened"},
    "display": "You have Advantage on saving throws you make to avoid or end the Frightened condition on yourself."
  },
  {
    "name": "Halfling Nimbleness",
    "logic": {"type": "movement", "pass_through_size": "larger"},
    "display": "You can move through the space of any creature that is of a size larger than yours."
  },
  {
    "name": "Luck",
    "logic": {"type": "reroll", "trigger": "roll_1", "applies_to": ["attack", "ability_check", "saving_throw"]},
    "display": "When you roll a 1 on the d20 for an attack roll, ability check, or saving throw, you can reroll the die and must use the new roll."
  },
  {
    "name": "Naturally Stealthy",
    "logic": {"type": "stealth", "obscured_by_size": "larger"},
    "display": "You can attempt to hide even when you are obscured only by a creature that is at least one size larger than you."
  }
]

[
  {"name": "Resourceful", "desc": "You gain Heroic Inspiration whenever you finish a Long Rest."},
  {"name": "Skillful", "logic": {"type": "proficiency", "options": ["Acrobatics", "Animal Handling", "Arcana", "Athletics", "Deception", "History", "Insight", "Intimidation", "Investigation", "Medicine", "Nature", "Perception", "Performance", "Persuasion", "Religion", "Sleight of Hand", "Stealth", "Survival"]}, "desc": "You gain proficiency in one skill of your choice."},
